Definition ax_writes (ax : axv) (m : word -> option byte) : word -> option byte :=
  match ax with
  | AX0 => m
  | AXg => wbytes (wbytes (wbytes (wbytes (m)
      (Z_to_bv 64 0xf88a0) (word_to_le_bytes 4 (Z_to_bv 64 0)))
      (Z_to_bv 64 0xf88a0) (word_to_le_bytes 4 (Z_to_bv 64 18446744073709551615)))
      (Z_to_bv 64 0xf88a0) (word_to_le_bytes 4 (Z_to_bv 64 32)))
      (Z_to_bv 64 0xf88a8) (word_to_le_bytes 8 (Z_to_bv 64 0))
  | AXgc => wbytes (wbytes (wbytes (wbytes (wbytes (m)
      (Z_to_bv 64 0xf88a0) (word_to_le_bytes 4 (Z_to_bv 64 1)))
      (Z_to_bv 64 0xf88a0) (word_to_le_bytes 4 (Z_to_bv 64 0)))
      (Z_to_bv 64 0xf88a0) (word_to_le_bytes 4 (Z_to_bv 64 18446744073709551615)))
