      (Z_to_bv 64 0xf88a0) (word_to_le_bytes 4 (Z_to_bv 64 32)))
      (Z_to_bv 64 0xf88a8) (word_to_le_bytes 8 (Z_to_bv 64 0))
  | AXgcs => wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (m)
      (Z_to_bv 64 0xf88a0) (word_to_le_bytes 4 (Z_to_bv 64 3)))
      (Z_to_bv 64 0xf88a0) (word_to_le_bytes 4 (Z_to_bv 64 2)))
      (Z_to_bv 64 0xf88a0) (word_to_le_bytes 4 (Z_to_bv 64 1)))
