(* [comment removed for export] *)
Definition mem_w2 (mem : word -> option byte) (sp code s1v : word) :=
  wbytes (wbytes (wbytes (wbytes (wbytes (wbytes mem
    (Z_to_bv 64 (bv_unsigned sp - 24)) (word_to_le_bytes 8 (Z_to_bv 64 0xa9338)))
    (Z_to_bv 64 (bv_unsigned sp - 32)) (word_to_le_bytes 8 code))
    (Z_to_bv 64 (bv_unsigned sp - 40)) (word_to_le_bytes 8 s1v))
    (Z_to_bv 64 (bv_unsigned sp - 56)) (word_to_le_bytes 8 (Z_to_bv 64 0xa92b4)))
    (Z_to_bv 64 (bv_unsigned sp - 64)) (word_to_le_bytes 8 (Z_to_bv 64 0xbf9e8)))
    (Z_to_bv 64 0xc6e18) [Z_to_bv 8 1].

Lemma w2 : forall regs mem rom (sp code s1v : word),
  getr regs 2 = Z_to_bv 64 (bv_unsigned sp - 16) -> getr regs 8 = code ->
  getr regs 1 = Z_to_bv 64 0xa9338 -> getr regs 9 = s1v ->
  (4294967296 <= bv_unsigned sp - 144)%Z -> (bv_unsigned sp <= 0x800000000000)%Z ->
  store_ok RSEGS mem (Z_to_bv 64 (bv_unsigned sp - 144)) 144%nat = true ->
  rdn RSEGS mem (Z_to_bv 64 0xc5ac0) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0xbf9f0)) ->
  rdn RSEGS mem (Z_to_bv 64 0xc5ac8) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0xbf9e8)) ->
  rdn RSEGS mem (Z_to_bv 64 0xbf9e8) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0x38b9c)) ->
  rdn RSEGS mem (Z_to_bv 64 0xc6e18) 1%nat = Some [Z_to_bv 8 0] ->
  rdn RSEGS mem (Z_to_bv 64 0xc5950) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0xa90ec)) ->
  rdn RSEGS mem (Z_to_bv 64 0xc6ae8) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0xc6ae8)) ->
  rdn RSEGS mem (Z_to_bv 64 0xc5958) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0)) ->
  exists regs',
    msteps RSEGS (mkst regs (0xa9284 : word) mem rom)
                 (mkst regs' (0xae974 : word) (mem_w2 mem sp code s1v) rom)
    /\ getr regs' 2 = Z_to_bv 64 (bv_unsigned sp - 16)
    /\ getr regs' 8 = code
    /\ getr regs' 1 = Z_to_bv 64 0xa933c
    /\ getr regs' 9 = s1v
